# region: digest
def digest(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: sift
def sift(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: emit
def emit(xs, limit=9):
    return [v if v <= limit else limit for v in xs]

# region: shape
def shape(xs, limit=9):
    return [v if v <= limit else limit for v in xs[1:]]

# region: gather
def gather(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: intake
def intake(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(gather(shape(emit(sift(digest(raw))))))

